/**
 * Every locale carries every key.
 *
 * There used to be an `OptionalTranslationKey` group here, so that copy added
 * in English and Japanese could compile while the other eighteen dictionaries
 * caught up and fell back to English at runtime. All twenty are complete now,
 * so the fallback has no work left to do and the type is total instead: a key
 * added to `TranslationKey` will not compile until all twenty locales define
 * it, which is the only way English cannot quietly resurface in another
 * language. `translate()` keeps its own defensive fallback for a *stored*
 * language tag the app no longer ships.
 */
type Dict = Record<TranslationKey, string>;

