  ai_voice_info_body: '所传输的数据绝不会用于生成所请求的高质量 AI 语音以外的任何目的。\n\n沃德科尔 服务器还会接收匿名安装 ID 和匿名订阅 ID，其唯一用途是验证您的方案并防止滥用。这些标识符不会发送给 OpenAI。\n\n未经您的许可，不会传输任何数据。您可以随时在此界面撤回许可。',
  voice_pick_info_title: '自然 AI 语音',
  voice_pick_info_body: '选择新的语音类型并点击返回按钮后，系统会为您的单词卡生成 AI Voice。\n\n使用 AI Voice 生成并播放音频后，音频会保存在设备本地。重新播放本地保存的音频时，不会重新连接在线 AI 语音服务，也不会再消耗一次 AI Voice 生成额度。\n\n首次播放时，尤其是文本较长时，沃德科尔 需要连接在线 AI 语音服务并生成音频，因此可能需要一些时间。',
