  analytics_setting_desc: '沃德科尔 使用 PostHog 进行产品分析和经过遮盖的 Session Replay。它会收集应用内的操作、设备的技术信息，以及已获批准的调研项目：推算年龄、性别、了解渠道、母语、学习语言和学习目的。您的确切出生日期不会被发送。\n\n您创建的单词、释义、笔记、文件夹名称、导入的内容和备份内容都不会被发送。\n\n这些数据帮助我们了解 沃德科尔 的使用情况并改进应用。它不会用于广告，也不会用于跨应用或跨网站的追踪。\n\n分析事件保留约 12 个月，Session Replay 录制保留约 30 天。您可以随时关闭共享。',
