  analytics_setting: 'Compartir datos de uso',
  analytics_setting_desc: 'WordCore usa PostHog para la analítica de producto y para Session Replay con enmascaramiento. Recoge las interacciones con la app, información técnica del dispositivo y estos datos de investigación aprobados: edad calculada, género, cómo conociste la app, lengua materna, idioma que estudias y objetivo de aprendizaje. Tu fecha de nacimiento exacta no se envía.\n\nLas palabras, los significados, las notas, los nombres de carpeta, el contenido importado y el contenido de las copias de seguridad que tú creas no se envían.\n\nEstos datos nos ayudan a entender cómo se usa WordCore y a mejorar la app. No se usan para publicidad ni para rastrearte entre apps o sitios web.\n\nLos eventos de analítica se conservan unos 12 meses y las grabaciones de Session Replay unos 30 días. Puedes desactivar el envío cuando quieras.',
