  result_filter_title: 'Filtrar por resultados del test',
  result_filter_intro: 'Cada respuesta que das en el modo test fija el resultado de esa palabra y le concede un tiempo de espera antes de que vuelvas a verla. Toca un botón de color para leer qué significa ese resultado y abrir las palabras que guarda, donde puedes borrar las que ya no quieras. Toca el botón gris para dejar en la lista solo las palabras listas para el test ahora —nunca probadas o con la espera cumplida— y tócalo otra vez para quitar el filtro.',
