  result_filter_title: 'Filtrer par résultat de test',
  result_filter_intro: 'Chaque réponse donnée en mode test fixe le résultat du mot et lui accorde un délai avant que vous ne le revoyiez. Appuyez sur un bouton coloré pour lire la signification de ce résultat et ouvrir les mots qu’il retient, où vous pouvez supprimer ceux dont vous ne voulez plus. Appuyez sur le bouton gris pour ne garder que les mots prêts à être testés maintenant — jamais testés ou dont le délai est écoulé — et appuyez à nouveau pour retirer le filtre.',
