  privacy_controls_section: 'Privacy',
  analytics_setting: 'Condividi dati di utilizzo',
  analytics_setting_desc: 'WordCore usa PostHog per l’analisi di prodotto e per Session Replay con mascheramento. Raccoglie le interazioni con l’app, informazioni tecniche sul dispositivo e questi dati di ricerca approvati: età calcolata, genere, come hai conosciuto l’app, lingua madre, lingua che stai studiando e obiettivo di apprendimento. La tua data di nascita esatta non viene inviata.\n\nLe parole, i significati, le note, i nomi delle cartelle, i contenuti importati e i contenuti dei backup che crei tu non vengono inviati.\n\nQuesti dati ci aiutano a capire come viene usato WordCore e a migliorare l’app. Non vengono usati per pubblicità né per tracciarti tra app o siti web.\n\nGli eventi di analisi sono conservati per circa 12 mesi e le registrazioni di Session Replay per circa 30 giorni. Puoi disattivare la condivisione quando vuoi.',
