  help_section: 'Aiuto',
  result_filter_title: 'Filtra per risultato del test',
  result_filter_intro: 'Ogni risposta che dai in modalità test fissa il risultato di quella parola e le assegna un tempo di attesa prima di rivederla. Tocca un pulsante colorato per leggere che cosa significa quel risultato e aprire le parole che tiene da parte, dove puoi eliminare quelle che non ti servono più. Tocca il pulsante grigio per ridurre l’elenco alle parole pronte per il test adesso — mai testate o con l’attesa conclusa — e toccalo di nuovo per togliere il filtro.',
  result_filter_perfect_note: '«Perfetto!» non ha un pulsante dedicato: quelle parole contano come completate e non compaiono più in questi filtri. Con «Sincronizza con i risultati dei test» attivo, escono anche dall’elenco delle parole.',
