  ai_voice_info_body: 'भेजे गए डेटा का उपयोग माँगी गई उच्च-गुणवत्ता वाली AI Voice जनरेट करने के अलावा किसी भी अन्य उद्देश्य के लिए कभी नहीं किया जाता।\n\nवर्डकोर सर्वर आपके प्लान की पुष्टि करने और दुरुपयोग रोकने के एकमात्र उद्देश्य से एक अनाम इंस्टॉलेशन ID और एक अनाम सब्सक्रिप्शन ID भी प्राप्त करता है। ये आइडेंटिफ़ायर OpenAI को नहीं भेजे जाते।\n\nआपकी अनुमति के बिना कोई डेटा नहीं भेजा जाता। आप इस स्क्रीन से कभी भी अनुमति वापस ले सकते हैं।',
  voice_pick_info_title: 'प्राकृतिक AI आवाज़',
  voice_pick_info_body: 'नया वॉयस प्रकार चुनकर वापस जाएँ बटन टैप करने पर आपके शब्द कार्ड के लिए AI Voice जनरेट की जाएगी।\n\nAI Voice के साथ ऑडियो जनरेट और चलाए जाने के बाद, उसे डिवाइस पर स्थानीय रूप से सहेजा जाता है। स्थानीय रूप से सहेजे गए ऑडियो को दोबारा चलाने पर ऑनलाइन AI वॉयस सेवा से फिर कनेक्ट नहीं होता और AI Voice जनरेशन का एक और क्रेडिट खर्च नहीं होता।\n\nपहली बार चलाने पर, खासकर लंबे टेक्स्ट के लिए, वर्डकोर को ऑनलाइन AI वॉयस सेवा से कनेक्ट करके ऑडियो जनरेट करने में कुछ समय लग सकता है।',
