  // ── Privacy & purchase feedback ───────────────────────────────────────────
  privacy_controls_section: 'गोपनीयता',
  analytics_setting: 'उपयोग डेटा साझा करें',
  analytics_setting_desc: 'वर्डकोर उत्पाद विश्लेषण और मास्क किए गए Session Replay के लिए PostHog का उपयोग करता है। यह ऐप में की गई क्रियाएँ, डिवाइस की तकनीकी जानकारी, और ये स्वीकृत शोध जानकारियाँ इकट्ठा करता है: अनुमानित आयु, लिंग, आपको ऐप के बारे में कैसे पता चला, मातृभाषा, सीखी जा रही भाषा, और सीखने का उद्देश्य। आपकी सटीक जन्म तिथि नहीं भेजी जाती।\n\nआपके बनाए शब्द, अर्थ, नोट, फ़ोल्डर के नाम, आयात किया गया कंटेंट और बैकअप का कंटेंट नहीं भेजा जाता।\n\nयह डेटा हमें यह समझने में मदद करता है कि वर्डकोर कैसे इस्तेमाल होता है और ऐप को बेहतर बनाने में सहायक है। इसका उपयोग विज्ञापन के लिए या ऐप्स और वेबसाइटों के बीच ट्रैकिंग के लिए नहीं किया जाता।\n\nविश्लेषण इवेंट लगभग 12 महीने और Session Replay रिकॉर्डिंग लगभग 30 दिन तक रखी जाती हैं। आप साझा करना कभी भी बंद कर सकते हैं।',
