  privacy_controls_section: 'Gizlilik',
  analytics_setting: 'Kullanım verilerini paylaş',
  analytics_setting_desc: 'WordCore, ürün analitiği ve maskelenmiş Session Replay için PostHog kullanır. Uygulama içindeki etkileşimler, cihaza ait teknik bilgiler ve onaylanmış şu araştırma bilgileri toplanır: hesaplanan yaş, cinsiyet, uygulamayı nereden duyduğunuz, ana diliniz, öğrendiğiniz dil ve öğrenme amacınız. Tam doğum tarihiniz gönderilmez.\n\nOluşturduğunuz kelimeler, anlamlar, notlar, klasör adları, içe aktarılan içerik ve yedek içeriği gönderilmez.\n\nBu veriler WordCore’un nasıl kullanıldığını anlamamıza ve uygulamayı geliştirmemize yardımcı olur. Reklam için ya da uygulamalar veya web siteleri arasında takip için kullanılmaz.\n\nAnalitik olayları yaklaşık 12 ay, Session Replay kayıtları yaklaşık 30 gün saklanır. Paylaşımı istediğiniz zaman kapatabilirsiniz.',
