  analytics_setting: 'Gebruiksgegevens delen',
  analytics_setting_desc: 'WordCore gebruikt PostHog voor productanalyse en gemaskeerde Session Replay. Verzameld worden interacties in de app, technische apparaatgegevens en deze goedgekeurde onderzoeksgegevens: afgeleide leeftijd, geslacht, hoe je de app hebt leren kennen, moedertaal, taal die je leert en leerdoel. Je exacte geboortedatum wordt niet verzonden.\n\nDe woorden, betekenissen, notities, mapnamen, geïmporteerde inhoud en back-upinhoud die je zelf maakt, worden niet verzonden.\n\nDeze gegevens helpen ons te begrijpen hoe WordCore wordt gebruikt en de app te verbeteren. Ze worden niet gebruikt voor advertenties of om je te volgen tussen apps of websites.\n\nAnalysegebeurtenissen worden ongeveer 12 maanden bewaard en Session Replay-opnamen ongeveer 30 dagen. Je kunt delen op elk moment uitschakelen.',
