  result_filter_title: 'Filteren op testresultaat',
  result_filter_intro: 'Elk antwoord dat je in de testmodus geeft, bepaalt het resultaat van dat woord en levert het een wachttijd op voordat je het terugziet. Tik op een gekleurde knop om te lezen wat dat resultaat betekent en de woorden te openen die eronder liggen; daar kun je verwijderen wat je niet meer wilt. Tik op de grijze knop om je lijst te beperken tot de woorden die nu klaar zijn voor de test — nooit getest, of wachttijd voorbij — en tik opnieuw om het filter te wissen.',
  result_filter_perfect_note: '“Perfect!” heeft geen eigen knop: die woorden gelden als afgerond en verschijnen niet meer in deze filters. Met “Synchroniseren met testresultaten” aan verlaten ze ook je woordenlijst.',
