  result_filter_title: 'Lọc theo kết quả kiểm tra',
  result_filter_intro: 'Mỗi câu trả lời của bạn trong chế độ kiểm tra sẽ định ra kết quả của từ đó và cho từ một khoảng chờ trước khi bạn gặp lại. Nhấn một nút màu để đọc ý nghĩa của kết quả đó và mở những từ đang được giữ ở đó, nơi bạn có thể xóa những từ không cần nữa. Nhấn nút xám để thu gọn danh sách còn những từ sẵn sàng kiểm tra ngay — chưa từng kiểm tra, hoặc đã hết thời gian chờ — và nhấn lần nữa để bỏ lọc.',
