  ai_voice_info_body: 'ข้อมูลที่ส่งจะไม่ถูกนำไปใช้เพื่อวัตถุประสงค์ใดๆ นอกจากการสร้างเสียง AI คุณภาพสูงตามที่ร้องขอ\n\nเซิร์ฟเวอร์ เวิร์ดคอร์ ยังรับ ID การติดตั้งแบบไม่ระบุตัวตนและ ID การสมัครสมาชิกแบบไม่ระบุตัวตน โดยมีวัตถุประสงค์เพียงเพื่อตรวจสอบแพลนและป้องกันการใช้งานในทางที่ผิด ตัวระบุเหล่านี้จะไม่ถูกส่งไปยัง OpenAI\n\nจะไม่มีการส่งข้อมูลใดๆ หากไม่ได้รับอนุญาตจากคุณ คุณสามารถถอนการอนุญาตได้ทุกเมื่อจากหน้าจอนี้',
  voice_pick_info_title: 'เสียง AI เป็นธรรมชาติ',
  voice_pick_info_body: 'เมื่อคุณเลือกประเภทเสียงใหม่แล้วแตะปุ่มย้อนกลับ ระบบจะสร้าง AI Voice สำหรับการ์ดคำศัพท์ของคุณ\n\nหลังจากสร้างและเล่นเสียงด้วย AI Voice เสียงนั้นจะถูกจัดเก็บไว้ในอุปกรณ์ การเล่นเสียงที่จัดเก็บไว้ในอุปกรณ์ซ้ำจะไม่เชื่อมต่อกับบริการเสียง AI ออนไลน์อีกครั้ง และไม่ใช้เครดิตการสร้าง AI Voice เพิ่ม\n\nในการเล่นครั้งแรก โดยเฉพาะข้อความที่ยาว อาจใช้เวลาสักระยะขณะที่ เวิร์ดคอร์ เชื่อมต่อกับบริการเสียง AI ออนไลน์และสร้างเสียง',
