  privacy_controls_section: 'ความเป็นส่วนตัว',
  analytics_setting: 'แชร์ข้อมูลการใช้งาน',
  analytics_setting_desc: 'เวิร์ดคอร์ ใช้ PostHog สำหรับการวิเคราะห์ผลิตภัณฑ์และ Session Replay แบบปิดบังข้อมูล โดยเก็บการใช้งานภายในแอป ข้อมูลทางเทคนิคของอุปกรณ์ และข้อมูลการวิจัยที่ได้รับอนุมัติต่อไปนี้ ได้แก่ อายุที่คำนวณได้ เพศ ช่องทางที่คุณรู้จักแอป ภาษาแม่ ภาษาที่กำลังเรียน และจุดประสงค์ในการเรียน ทั้งนี้จะไม่มีการส่งวันเกิดที่แน่นอนของคุณ\n\nคำศัพท์ ความหมาย โน้ต ชื่อโฟลเดอร์ เนื้อหาที่นำเข้า และเนื้อหาสำรองข้อมูลที่คุณสร้างขึ้นจะไม่ถูกส่ง\n\nข้อมูลเหล่านี้ช่วยให้เราเข้าใจวิธีที่ผู้ใช้ใช้งาน เวิร์ดคอร์ และช่วยปรับปรุงแอป โดยจะไม่ถูกใช้เพื่อการโฆษณาหรือการติดตามข้ามแอปและเว็บไซต์\n\nเหตุการณ์การวิเคราะห์จะถูกเก็บไว้ประมาณ 12 เดือน และวิดีโอ Session Replay ประมาณ 30 วัน คุณสามารถปิดการแชร์ได้ตลอดเวลา',
