  analytics_setting: 'Bagikan data penggunaan',
  analytics_setting_desc: 'WordCore memakai PostHog untuk analitik produk dan Session Replay yang disamarkan. Yang dikumpulkan adalah interaksi di dalam aplikasi, informasi teknis perangkat, dan data riset yang telah disetujui berikut: perkiraan usia, jenis kelamin, dari mana kamu tahu aplikasi ini, bahasa ibu, bahasa yang dipelajari, dan tujuan belajar. Tanggal lahir persismu tidak dikirim.\n\nKata, arti, catatan, nama folder, konten yang diimpor, dan isi cadangan yang kamu buat sendiri tidak dikirim.\n\nData ini membantu kami memahami bagaimana WordCore digunakan dan memperbaiki aplikasinya. Data tidak dipakai untuk iklan atau untuk melacakmu antaraplikasi maupun antarsitus web.\n\nPeristiwa analitik disimpan sekitar 12 bulan dan rekaman Session Replay sekitar 30 hari. Kamu bisa mematikan berbagi kapan saja.',
