  help_section: 'Bantuan',
  result_filter_title: 'Saring menurut hasil tes',
  result_filter_intro: 'Setiap jawaban yang kamu berikan di mode tes menetapkan hasil kata itu dan memberinya waktu tunggu sebelum kamu melihatnya lagi. Ketuk tombol berwarna untuk membaca arti hasil tersebut dan membuka kata-kata yang tersimpan di sana, tempat kamu bisa menghapus yang sudah tidak diperlukan. Ketuk tombol abu-abu untuk menyaring daftar menjadi kata yang siap dites sekarang — yang belum pernah dites, atau yang waktu tunggunya sudah habis — dan ketuk sekali lagi untuk menghapus saringan.',
  result_filter_perfect_note: '“Hafal sekali” tidak punya tombol sendiri: kata-kata itu dianggap selesai dan tidak lagi muncul pada saringan ini. Jika “Sinkronkan dengan hasil tes” aktif, kata-kata itu juga keluar dari daftar katamu.',
