  analytics_setting_desc: 'WordCore korzysta z PostHog do analityki produktowej i zamaskowanego Session Replay. Zbierane są interakcje w aplikacji, informacje techniczne o urządzeniu oraz następujące zatwierdzone dane badawcze: wyliczony wiek, płeć, skąd znasz aplikację, język ojczysty, język, którego się uczysz, i cel nauki. Twoja dokładna data urodzenia nie jest wysyłana.\n\nTworzone przez Ciebie słówka, znaczenia, notatki, nazwy folderów, zaimportowana treść i zawartość kopii zapasowych nie są wysyłane.\n\nTe dane pomagają nam zrozumieć, jak używany jest WordCore, i ulepszać aplikację. Nie służą do reklam ani do śledzenia Cię między aplikacjami i witrynami.\n\nZdarzenia analityczne przechowujemy około 12 miesięcy, a nagrania Session Replay około 30 dni. Udostępnianie możesz wyłączyć w każdej chwili.',
