  result_filter_title: 'Filtruj według wyników testu',
  result_filter_intro: 'Każda odpowiedź w trybie testu ustala wynik danego słówka i daje mu czas oczekiwania, zanim zobaczysz je ponownie. Naciśnij kolorowy przycisk, aby przeczytać, co oznacza dany wynik, i otworzyć przetrzymywane pod nim słówka — tam możesz usunąć te, których już nie chcesz. Naciśnij szary przycisk, aby zawęzić listę do słówek gotowych do testu teraz — nigdy nietestowanych albo takich, którym minął czas oczekiwania — i naciśnij ponownie, aby wyłączyć filtr.',
