  analytics_setting_desc: 'Το ΓουόρντΚορ χρησιμοποιεί το PostHog για αναλυτικά στοιχεία προϊόντος και για Session Replay με απόκρυψη. Συλλέγονται οι ενέργειες μέσα στην εφαρμογή, τεχνικές πληροφορίες της συσκευής και τα εξής εγκεκριμένα ερευνητικά στοιχεία: υπολογισμένη ηλικία, φύλο, πώς μάθατε για την εφαρμογή, μητρική γλώσσα, γλώσσα που μαθαίνετε και σκοπός μάθησης. Η ακριβής ημερομηνία γέννησής σας δεν αποστέλλεται.\n\nΟι λέξεις, οι σημασίες, οι σημειώσεις, τα ονόματα φακέλων, το εισαγόμενο περιεχόμενο και το περιεχόμενο των αντιγράφων ασφαλείας που δημιουργείτε δεν αποστέλλονται.\n\nΑυτά τα δεδομένα μας βοηθούν να καταλάβουμε πώς χρησιμοποιείται το ΓουόρντΚορ και να βελτιώσουμε την εφαρμογή. Δεν χρησιμοποιούνται για διαφημίσεις ούτε για παρακολούθηση ανάμεσα σε εφαρμογές ή ιστότοπους.\n\nΤα συμβάντα αναλυτικών διατηρούνται περίπου 12 μήνες και οι εγγραφές Session Replay περίπου 30 ημέρες. Μπορείτε να απενεργοποιήσετε την κοινή χρήση όποτε θέλετε.',
