  help_section: 'Βοήθεια',
  result_filter_title: 'Φιλτράρισμα κατά αποτέλεσμα τεστ',
  result_filter_intro: 'Κάθε απάντηση που δίνετε στη λειτουργία τεστ καθορίζει το αποτέλεσμα της λέξης και της χαρίζει έναν χρόνο αναμονής προτού την ξαναδείτε. Πατήστε ένα χρωματιστό κουμπί για να διαβάσετε τι σημαίνει αυτό το αποτέλεσμα και να ανοίξετε τις λέξεις που κρατά, όπου μπορείτε να διαγράψετε όσες δεν θέλετε πια. Πατήστε το γκρι κουμπί για να περιοριστεί η λίστα στις λέξεις που είναι έτοιμες για τεστ τώρα — όσες δεν έχουν ελεγχθεί ποτέ ή έχουν ολοκληρώσει την αναμονή τους — και πατήστε το ξανά για να καθαρίσετε το φίλτρο.',
  result_filter_perfect_note: 'Το «Τέλεια!» δεν έχει δικό του κουμπί: οι λέξεις αυτές θεωρούνται ολοκληρωμένες και δεν εμφανίζονται πλέον σε αυτά τα φίλτρα. Με τον «Συγχρονισμό με τα αποτελέσματα των τεστ» ενεργό, φεύγουν και από τη λίστα λέξεων.',
