  privacy_controls_section: 'Integritet',
  analytics_setting: 'Dela användningsdata',
  analytics_setting_desc: 'WordCore använder PostHog för produktanalys och maskerad Session Replay. Det som samlas in är interaktioner i appen, teknisk information om enheten och dessa godkända undersökningsuppgifter: beräknad ålder, kön, hur du fick reda på appen, modersmål, språket du lär dig och ditt syfte med lärandet. Ditt exakta födelsedatum skickas inte.\n\nDe ord, betydelser, anteckningar, mappnamn, importerat innehåll och säkerhetskopieinnehåll som du själv skapar skickas inte.\n\nDe här uppgifterna hjälper oss att förstå hur WordCore används och att förbättra appen. De används inte för annonsering eller för att spåra dig mellan appar och webbplatser.\n\nAnalyshändelser sparas i ungefär 12 månader och Session Replay-inspelningar i ungefär 30 dagar. Du kan stänga av delningen när som helst.',
