/**
 * Maps BCP-47 TTS codes (used in onboarding / word cards) to app UI lang codes.
 * Used in App.tsx onComplete to default the UI language from the user's explanation language.
 */
export const BCP47_TO_UI_LANG: Record<string, string> = {
  'en-US': 'en-US', 'en-GB': 'en-US', 'en-AU': 'en-US',
  'es-ES': 'es', 'es-MX': 'es', 'es-US': 'es', 'es-419': 'es',
  'fr-FR': 'fr', 'fr-CA': 'fr',
  'ja-JP': 'ja',
  'ko-KR': 'ko',
  'zh-CN': 'zh-CN', 'zh-Hans': 'zh-CN',
  'de-DE': 'de',
  'it-IT': 'it',
  'pt-BR': 'pt-BR', 'pt-PT': 'pt-BR',
  'ru-RU': 'ru',
  'ar':    'ar', 'ar-SA': 'ar', 'ar-EG': 'ar',
  'hi-IN': 'hi',
  'tr-TR': 'tr',
  'nl-NL': 'nl',
  'vi-VN': 'vi',
  'th-TH': 'th',
  'id-ID': 'id',
  'pl-PL': 'pl',
  'el-GR': 'el',
  'sv-SE': 'sv',
};

export type LangCode = typeof SUPPORTED_LANGUAGES[number]['code'];

/** React context — value is the bound translate function for the active language. */
export const LangContext = createContext<(key: TranslationKey) => string>(
  (key: TranslationKey) => enUS[key] ?? key,
);

export const useLang = () => useContext(LangContext);
